import sys

def max_removals(s):
    n = len(s)
    dp = [0] * n

    for i in range(n):
        if i > 0 and s[i] == chr(ord(s[i-1]) + 1):
            dp[i] = max(dp[i], dp[i-1] + 1)
        if i < n - 1 and s[i] == chr(ord(s[i+1]) + 1):
            dp[i] = max(dp[i], (dp[i+1] if i+1 < n else 0) + 1)
        if i > 0:
            dp[i] = max(dp[i], dp[i-1])

    return dp[-1]

input = sys.stdin.read().split()
n = int(input[0])
s = input[1]
print(max_removals(s))
